import type { MatchPhase } from '../contracts/game';

const TRANSITIONS: Readonly<Record<MatchPhase, readonly MatchPhase[]>> = {
  lobby: ['hole-intro'],
  'hole-intro': ['aiming', 'match-results'],
  aiming: ['simulating', 'paused', 'hole-results'],
  simulating: ['aiming', 'paused', 'hole-results'],
  'hole-results': ['hole-intro', 'match-results'],
  'match-results': [],
  paused: ['aiming', 'simulating'],
};

export class GameplayStateMachine {
  private previousBeforePause?: MatchPhase;

  constructor(private phaseValue: MatchPhase = 'lobby') {}

  get phase(): MatchPhase {
    return this.phaseValue;
  }

  canTransition(next: MatchPhase): boolean {
    return TRANSITIONS[this.phaseValue].includes(next);
  }

  transition(next: MatchPhase): MatchPhase {
    if (!this.canTransition(next)) {
      throw new Error(`Invalid match phase transition: ${this.phaseValue} -> ${next}`);
    }
    if (next === 'paused') this.previousBeforePause = this.phaseValue;
    this.phaseValue = next;
    return this.phaseValue;
  }

  pause(): MatchPhase {
    if (this.phaseValue !== 'aiming' && this.phaseValue !== 'simulating') {
      throw new Error(`Cannot pause from ${this.phaseValue}`);
    }
    return this.transition('paused');
  }

  resume(): MatchPhase {
    if (this.phaseValue !== 'paused' || !this.previousBeforePause) {
      throw new Error('Cannot resume when match is not paused');
    }
    const target = this.previousBeforePause;
    this.previousBeforePause = undefined;
    this.phaseValue = target;
    return this.phaseValue;
  }
}
