import type { SimulationService } from '../contracts/services';
import type { GameplayShotRequest } from './types';

export interface ShotValidationResult {
  accepted: boolean;
  reason?: string;
}

export class ShotSystemAdapter {
  constructor(
    private readonly simulation: SimulationService,
    private readonly stopThreshold: number,
  ) {}

  submit(request: GameplayShotRequest): ShotValidationResult {
    const { command, phase, activePlayerId, ballSpeed } = request;
    if (phase !== 'aiming') return { accepted: false, reason: 'match-not-aiming' };
    if (activePlayerId !== command.playerId) return { accepted: false, reason: 'not-active-player' };
    if (ballSpeed > this.stopThreshold) return { accepted: false, reason: 'ball-moving' };
    if (!(command.normalizedPower > 0 && command.normalizedPower <= 1)) return { accepted: false, reason: 'invalid-power' };
    const accepted = this.simulation.submitShot(command);
    return accepted ? { accepted: true } : { accepted: false, reason: 'simulation-rejected' };
  }
}
