import type { SimulationEvent } from '../contracts/events';
import type { MatchDTO, MatchSettings, PlayerHoleScore, PlayerProfile } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { GameplayStateMachine } from './StateMachine';
import { ScoreManager } from './ScoreManager';
import { TurnManager } from './TurnManager';

export class MatchManager {
  private readonly scoreManager = new ScoreManager();
  private readonly turnManager = new TurnManager();
  private stateMachine = new GameplayStateMachine('lobby');

  createMatch(id: string, settings: MatchSettings, players: readonly PlayerProfile[]): MatchDTO {
    if (players.length < 1 || players.length > settings.maxPlayers) throw new Error('Invalid player count');
    this.stateMachine = new GameplayStateMachine('lobby');
    return {
      id,
      phase: 'lobby',
      settings,
      players: players.map(player => ({ ...player, connected: true, totalStrokes: 0, holeScores: [] })),
      currentHoleIndex: 0,
    };
  }

  startMatch(match: MatchDTO, course: Course, now = Date.now()): MatchDTO {
    if (course.id !== match.settings.courseId) throw new Error('Course does not match match settings');
    if (course.holes.length === 0) throw new Error('Course has no holes');
    this.stateMachine = new GameplayStateMachine(match.phase);
    this.stateMachine.transition('hole-intro');
    return this.prepareHole({ ...match, phase: this.stateMachine.phase, startedAt: now }, course.holes[0]);
  }

  beginAiming(match: MatchDTO, hole: Hole): MatchDTO {
    this.syncStateMachine(match.phase);
    this.stateMachine.transition('aiming');
    return { ...match, phase: this.stateMachine.phase, activePlayerId: this.turnManager.firstEligiblePlayer(match, hole.id) };
  }

  markShotSubmitted(match: MatchDTO): MatchDTO {
    this.syncStateMachine(match.phase);
    this.stateMachine.transition('simulating');
    return { ...match, phase: this.stateMachine.phase };
  }

  applySimulationEvent(match: MatchDTO, course: Course, event: SimulationEvent, now = Date.now()): MatchDTO {
    const hole = course.holes[match.currentHoleIndex];
    if (!hole) throw new Error('Current hole does not exist');

    if (event.type === 'shot-accepted') {
      return this.updateScore(match, event.command.playerId, hole.id, score => this.scoreManager.recordStroke(score));
    }

    if (event.type === 'ball-reset') {
      return this.updateScore(match, event.playerId, hole.id, score => this.scoreManager.addPenalty(score, event.penaltyStrokes));
    }

    if (event.type === 'ball-holed') {
      const completed = this.updateScore(match, event.playerId, hole.id, score => this.scoreManager.complete(score, now - (match.startedAt ?? now)));
      return this.advanceAfterPlayerFinished(completed, course, hole.id, now);
    }

    if (event.type === 'ball-stopped') {
      return this.advanceTurn(match, course, hole.id, match.activePlayerId ?? event.playerId, now);
    }

    return match;
  }

  enforceStrokeLimit(match: MatchDTO, course: Course, playerId: string, now = Date.now()): MatchDTO {
    const hole = course.holes[match.currentHoleIndex];
    if (!hole) throw new Error('Current hole does not exist');
    const updated = this.updateScore(match, playerId, hole.id, score => this.scoreManager.applyStrokeLimit(score, match.settings.strokeLimitPerHole));
    const score = this.findScore(updated, playerId, hole.id);
    return score.completed ? this.advanceAfterPlayerFinished(updated, course, hole.id, now) : updated;
  }

  pause(match: MatchDTO): MatchDTO {
    this.syncStateMachine(match.phase);
    this.stateMachine.pause();
    return { ...match, phase: this.stateMachine.phase };
  }

  resume(match: MatchDTO): MatchDTO {
    if (this.stateMachine.phase !== 'paused') this.stateMachine = new GameplayStateMachine('paused');
    const phase = this.stateMachine.resume();
    return { ...match, phase };
  }

  private prepareHole(match: MatchDTO, hole: Hole): MatchDTO {
    const players = match.players.map(player => {
      if (player.holeScores.some(score => score.holeId === hole.id)) return player;
      return { ...player, holeScores: [...player.holeScores, this.scoreManager.createHoleScore(player.id, hole.id)] };
    });
    return { ...match, players, activePlayerId: undefined };
  }

  private advanceTurn(match: MatchDTO, course: Course, holeId: string, currentPlayerId: string, now: number): MatchDTO {
    if (this.turnManager.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
    const activePlayerId = this.turnManager.nextEligiblePlayer(match, holeId, currentPlayerId);
    this.syncStateMachine(match.phase);
    if (this.stateMachine.phase === 'simulating') this.stateMachine.transition('aiming');
    return { ...match, phase: this.stateMachine.phase, activePlayerId };
  }

  private advanceAfterPlayerFinished(match: MatchDTO, course: Course, holeId: string, now: number): MatchDTO {
    if (this.turnManager.allPlayersFinishedHole(match, holeId)) return this.finishHole(match, course, now);
    return this.advanceTurn(match, course, holeId, match.activePlayerId ?? match.players[0]?.id ?? '', now);
  }

  private finishHole(match: MatchDTO, course: Course, now: number): MatchDTO {
    this.syncStateMachine(match.phase);
    if (this.stateMachine.phase === 'simulating' || this.stateMachine.phase === 'aiming') this.stateMachine.transition('hole-results');
    const isLastHole = match.currentHoleIndex >= course.holes.length - 1;
    if (isLastHole) {
      this.stateMachine.transition('match-results');
      const standings = this.scoreManager.standings(match.players);
      const totals = new Map(standings.map(row => [row.playerId, row.totalStrokes]));
      return {
        ...match,
        phase: this.stateMachine.phase,
        activePlayerId: undefined,
        finishedAt: now,
        players: match.players.map(player => ({ ...player, totalStrokes: totals.get(player.id) ?? player.totalStrokes })),
      };
    }

    this.stateMachine.transition('hole-intro');
    const nextIndex = match.currentHoleIndex + 1;
    const nextHole = course.holes[nextIndex];
    if (!nextHole) throw new Error('Next hole does not exist');
    return this.prepareHole({ ...match, phase: this.stateMachine.phase, currentHoleIndex: nextIndex }, nextHole);
  }

  private updateScore(match: MatchDTO, playerId: string, holeId: string, updater: (score: PlayerHoleScore) => PlayerHoleScore): MatchDTO {
    return {
      ...match,
      players: match.players.map(player => {
        if (player.id !== playerId) return player;
        const holeScores = player.holeScores.map(score => score.holeId === holeId ? updater(score) : score);
        return { ...player, holeScores, totalStrokes: holeScores.reduce((sum, score) => sum + score.strokes, 0) };
      }),
    };
  }

  private findScore(match: MatchDTO, playerId: string, holeId: string): PlayerHoleScore {
    const score = match.players.find(player => player.id === playerId)?.holeScores.find(entry => entry.holeId === holeId);
    if (!score) throw new Error(`Missing score for player ${playerId} on hole ${holeId}`);
    return score;
  }

  private syncStateMachine(phase: MatchDTO['phase']): void {
    if (this.stateMachine.phase !== phase) this.stateMachine = new GameplayStateMachine(phase);
  }
}
