import { describe, expect, it } from 'vitest';
import type { MatchPlayer, PlayerProfile } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { GameplayStateMachine } from './StateMachine';
import { HoleSystem } from './HoleSystem';
import { MatchManager } from './MatchManager';
import { ScoreManager } from './ScoreManager';

const hole = (id: string, par = 3): Hole => ({
  id,
  name: id,
  par,
  spawn: { x: 0, y: 0, z: 0 },
  cup: { position: { x: 5, y: 0, z: 0 }, radius: 0.3, captureDepth: 0.25 },
  bounds: { min: { x: -2, y: -2, z: -2 }, max: { x: 10, y: 3, z: 2 } },
  surfaces: [],
  obstacles: [],
});

const player = (id: string): PlayerProfile => ({ id, displayName: id, kind: 'human', ballStyleId: 'default', rating: 1000 });

const course: Course = { id: 'c1', name: 'Course', themeId: 'test', version: 1, holes: [hole('h1'), hole('h2', 4)] };

describe('ScoreManager', () => {
  it('tracks strokes, penalties, limits and par labels', () => {
    const manager = new ScoreManager();
    let score = manager.createHoleScore('p1', 'h1');
    score = manager.recordStroke(score);
    score = manager.addPenalty(score);
    expect(score.strokes).toBe(2);
    expect(score.penaltyStrokes).toBe(1);
    expect(manager.parLabel(2, 3)).toBe('BIRDIE');
    expect(manager.parLabel(3, 3)).toBe('PAR');
    expect(manager.parLabel(4, 3)).toBe('BOGEY');
    expect(manager.applyStrokeLimit({ ...score, strokes: 5 }, 5).completed).toBe(true);
  });

  it('orders match results using deterministic tiebreakers', () => {
    const manager = new ScoreManager();
    const players: MatchPlayer[] = [
      { ...player('slow'), connected: true, totalStrokes: 0, holeScores: [{ playerId:'slow', holeId:'h1', strokes:3, completed:true, penaltyStrokes:0, completionTimeMs:9000 }] },
      { ...player('fast'), connected: true, totalStrokes: 0, holeScores: [{ playerId:'fast', holeId:'h1', strokes:3, completed:true, penaltyStrokes:0, completionTimeMs:5000 }] },
      { ...player('penalty'), connected: true, totalStrokes: 0, holeScores: [{ playerId:'penalty', holeId:'h1', strokes:3, completed:true, penaltyStrokes:1, completionTimeMs:1000 }] },
    ];
    expect(manager.standings(players).map(row => row.playerId)).toEqual(['fast', 'slow', 'penalty']);
  });
});

describe('HoleSystem', () => {
  it('requires low speed for cup capture and resets hazards to last safe position', () => {
    const system = new HoleSystem(1.2);
    const testHole = hole('h1');
