    expect(system.isBallHoled(testHole, { x: 5.1, y: 0, z: 0 }, 2)).toBe(false);
    system.setInitialSafePosition('p1', testHole.spawn);
    system.markSafePosition('p1', { x: 2, y: 0, z: 0 });
    expect(system.resolveHazard('p1', testHole)).toEqual({ playerId:'p1', resetPosition:{ x:2, y:0, z:0 }, penaltyStrokes:1 });
  });
});

describe('GameplayStateMachine', () => {
  it('enforces legal transitions and restores phase after pause', () => {
    const machine = new GameplayStateMachine();
    machine.transition('hole-intro');
    machine.transition('aiming');
    expect(machine.pause()).toBe('paused');
